async function send(){
const v=(elInput.value||"").trim()
if(!v){showToast("Adj meg üzenetet");return}
addMessage(v,"user")
elInput.value=""
try{
const r=await fetch(api,{method:"POST",headers:{"ContentType":"application/json"},body:JSON.stringify({message:v})})
if(!r.ok){
addMessage("Hiba: szerver nem elérhető","ai")
return
}
const data=await r.json()
if(data.error){
addMessage("Hiba: "+data.error,"ai")
return
}
addMessage(data.response,"ai")
}catch(e){
addMessage("Hálózati hiba","ai")
}
}
elSend.addEventListener("click",send)
elInput.addEventListener("keydown",function(e){if(e.key==="Enter"){send()}})
addMessage("Üdvözöl a JAIDE 12.5. Írj üzenetet.","ai")
})()
