import os,hashlib,hmac,json,glob

ROOT=os.path.abspath(os.path.join(os.path.dirname(__file__),".."))
def read(p):
    with open(p,"rb") as f:return f.read()
def write(p,b):
    with open(p,"wb") as f:f.write(b)
def strip_and_seal(p,a,b,c):
    data=read(p)
    marker=b"\n__FP_BLOCK_BEGIN__\n"
    body,tail=(data.split(marker,1)+[None])[:2] if marker in data else (data,None)
    h=hmac.new(a,body,hashlib.sha256);h.update(b);h.update(c)
    fp=h.hexdigest()
    blob=body+marker+json.dumps({"path":os.path.relpath(p,ROOT),"hmac":fp}).encode("utf8")
    write(p,blob)

def parts():
    a=b"\x9f\x13\xaa\x71\x02\xf1\x6b\xcd\x44\x10\x98\x3c\x5d\x21\x7e\x4b\x2a\xac\x10\xe1\xbb\x56\x88\x41\x02\x10\x77\xb4\x9d\x0f\x18\x91"
    b_part=os.environ.get("FP_KEY_PART","").encode("utf8")
    c_seed=b"iospwafpseed"
    c=hmac.new(a,c_seed,hashlib.sha256).digest()
    return a,b_part,c

def main():
    a,b,c=parts()
    targets=[]
    targets+=glob.glob(os.path.join(ROOT,"backend",".py"))
    targets+=glob.glob(os.path.join(ROOT,"frontend",".html"))
    targets+=glob.glob(os.path.join(ROOT,"frontend","static",".css"))
    targets+=glob.glob(os.path.join(ROOT,"frontend","static",".js"))
    targets+=glob.glob(os.path.join(ROOT,"frontend","static",".json"))
    for p in targets:
        strip_and_seal(p,a,b,c)

if __name__=="__main__":
    main()
